/// The items below are pub(crate).
/// One painted row of the tree pane.
#[derive(Clone, Debug, PartialEq, Eq)]
struct TreeRow {
    pub depth: u32,
    pub name: String,
    pub path: std::path::PathBuf,
    pub is_dir: bool,
    pub expanded: bool,
}

/// The items below are pub(crate).
/// Rows in paint order for the expanded directories.
fn visible_rows(root: &TreeNode, expanded: &std::collections::BTreeSet<std::path::PathBuf>) -> Vec<TreeRow>
